<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {hours} from '../time'
import {reviewBoardText} from '../approvalWorkbench'
import type {ReviewPreview} from '../approvalWorkbench'
const props=defineProps<{data:ReviewPreview;disabled:boolean;english:boolean;failure:string;processed:number;retry:boolean}>(),emit=defineEmits<{close:[];confirm:[string];recover:[]}>(),dialog=ref<HTMLDialogElement|null>(null),note=ref(''),offset=ref(0)
const b=(key:Parameters<typeof reviewBoardText>[0])=>reviewBoardText(key,props.english),page=computed(()=>props.data.items.slice(offset.value,offset.value+50))
onMounted(()=>dialog.value?.showModal?.());onBeforeUnmount(()=>dialog.value?.close?.())
</script>
<template><dialog ref="dialog" class="wf-schedule-dialog wf-approval-preview" aria-modal="true" :aria-label="b('preview')" @cancel.prevent="!disabled&&emit('close')"><header class="wf-toolbar"><h2>{{b('preview')}}</h2><button :disabled="disabled" @click="emit('close')">{{b('close')}}</button></header><p>{{b('total')}} {{data.items.length}} · {{b('work')}} {{hours(data.workSeconds)}} · {{b('paid')}} {{hours(data.paidLeaveSeconds)}} · {{b('unpaid')}} {{hours(data.unpaidLeaveSeconds)}}</p><p class="wf-hint">{{b('chunkHint')}}</p><p v-if="failure" role="alert" class="wf-error">{{failure}}</p><p v-if="retry" role="status">{{b('retryHint')}}</p><p v-if="processed">{{b('done')}} {{processed}} / {{data.items.length}}</p><div class="wf-table-wrap"><table><thead><tr><th>{{b('date')}}</th><th>{{b('employee')}}</th><th>{{b('work')}}</th><th>{{b('paid')}}</th><th>{{b('unpaid')}}</th></tr></thead><tbody><tr v-for="row in page" :key="row.scheduleId"><td>{{row.date}}</td><td>{{row.employeeName}} {{row.employeeNo}}</td><td>{{hours(row.workSeconds)}}</td><td>{{hours(row.paidLeaveSeconds)}}</td><td>{{hours(row.unpaidLeaveSeconds)}}</td></tr></tbody></table></div><div class="wf-form-actions"><button :disabled="disabled||offset===0" @click="offset-=50">{{b('previous')}}</button><span>{{offset+1}}–{{Math.min(offset+50,data.items.length)}} / {{data.items.length}}</span><button :disabled="disabled||offset+50>=data.items.length" @click="offset+=50">{{b('next')}}</button></div><label>{{b('note')}}<textarea v-model="note" rows="2" maxlength="500" :disabled="disabled"></textarea></label><footer class="wf-form-actions"><button v-if="retry" class="primary" @click="emit('recover')">{{b('retry')}}</button><button v-else class="primary" :disabled="disabled" @click="emit('confirm',note.trim())">{{b('confirm')}}</button></footer></dialog></template>
<style scoped>.wf-approval-preview{width:min(1000px,calc(100vw - 24px));max-width:calc(100vw - 24px);max-height:90vh;overflow:auto}.wf-approval-preview::backdrop{background:rgb(15 28 42 / 42%)}</style>
